    {
      "type": "predicate",
      "name": "is_frustrated",
      "instructions": "Is the customer frustrated?"
    },
    {
      "type": "choice",
      "name": "category",
      "instructions": "Pick the ticket category",
      "choices": [
        {
          "value": "billing",
          "description": "charges, refunds, invoices"
        },
        {
          "value": "bug",
          "description": "product defects"
        },
        {
          "value": "other",
          "description": "anything else"
        }
      ]
    },
    {
      "type": "score",
      "name": "urgency",
      "instructions": "Rate how urgently this ticket needs a human reply",
      "levels": [
        {
          "label": "0",
          "description": "can wait a week"
        },
        {
          "label": "1",
          "description": "should be answered soon"
        },
        {
          "label": "2",
          "description": "needs a reply today"
        }
      ]
    }
  ]
}

